    """Run-length encode a string of letters.

    Each run becomes the character followed by its length, except that a
    length of 1 is omitted.  For example, 'aaabcc' -> 'a3bc2'.
    """
    if not s:
        return ''

    result = []
    current = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            result.append(current + (str(count) if count != 1 else ''))
            current = ch
            count = 1

    result.append(current + (str(count) if count != 1 else ''))
    return ''.join(result)


def decode(s):
    """Decode a string produced by encode."""
    result = []
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]
        i += 1

        start = i
        while i < n and s[i].isdigit():
